def require_limit(value: int) -> int:
    if value < 0:
        raise ValueError("limit must be nonnegative")
    return value

func label(n int) (string, error) {
    if n < 0 { return "", fmt.Errorf("negative index: %d", n) }
    return fmt.Sprintf("item-%d", n), nil
}

func lookup(m map[string]int, key string) (int, bool) {
    value, ok := m[key]
    return value, ok
}

fn positive(n: i64) -> Result<u64, &'static str> {
    u64::try_from(n).map_err(|_| "negative value")
}

fn active<'a>(items: &'a [(&'a str, bool)]) -> Vec<&'a str> {
    items.iter().filter(|(_, ok)| *ok).map(|(name, _)| *name).collect()
}
